package com.dronefleet.strategy;import com.dronefleet.domain.*;public final class DroneCalculator{private DroneCalculator(){}public static double battery(Drone d,PackageItem p){return switch(d.type()){case "Heavy"->p.distance()*.6+p.weight()*.25;case "Express"->p.distance()*.55+p.weight()*.2;default->p.distance()*.5+p.weight()*.2;};}public static int minutes(Drone d,PackageItem p){return switch(d.type()){case "Heavy"->(int)Math.ceil(p.distance()*2.2+p.weight()*1.1);case "Express"->(int)Math.ceil(p.distance()*1.4+p.weight()*.8);default->(int)Math.ceil(p.distance()*2+p.weight());};}public static double charge(Drone d,PackageItem p){int t=minutes(d,p);return switch(d.type()){case "Heavy"->t*24+p.distance()*34+450;case "Express"->t*32+p.distance()*40+600;default->t*20+p.distance()*30+300;};}}
